package com.collabspace.websocket; import com.collabspace.security.JwtService; import org.springframework.messaging.Message; import org.springframework.messaging.MessageChannel; import org.springframework.messaging.support.ChannelInterceptor; import org.springframework.messaging.simp.stomp.*; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.stereotype.Component; import java.util.*; @Component public class WebSocketAuthInterceptor implements ChannelInterceptor {private final JwtService jwt; public WebSocketAuthInterceptor(JwtService jwt){this.jwt=jwt;} public Message<?> preSend(Message<?> message,MessageChannel channel){StompHeaderAccessor a=StompHeaderAccessor.wrap(message);if(StompCommand.CONNECT.equals(a.getCommand())){String h=a.getFirstNativeHeader("Authorization");if(h!=null&&h.startsWith("Bearer ")){try{String email=jwt.extractUsername(h.substring(7));if(jwt.isTokenValid(h.substring(7)))a.setUser(new UsernamePasswordAuthenticationToken(email,null,List.of()));}catch(Exception ignored){}}}return message;}}